def digest(data):
    return hashlib.sha256(data).hexdigest()

def reconstruct(repo):
    topic=Path(repo).resolve()/'topics/visible-flex-larger-amplitude'
    answers=[]
    for item in PLAN['files']:
        raw=(topic/item['parent_path']).read_bytes()
        if digest(raw)!=item['parent_sha256'] or len(raw)!=item['parent_bytes']:
            raise ValueError('The complete original parent source differs: '+item['parent_path'])
        before=raw.decode('utf-8')
        text=before
        for patch in item['patches']:
            if text.count(patch['old'])!=patch['count']:
                raise ValueError('The exact full parent text delta no longer applies')
            text=text.replace(patch['old'],patch['new'])
        output=text.encode('utf-8')
        if digest(output)!=item['output_sha256'] or len(output)!=item['output_bytes']:
            raise ValueError('Complete derived source does not match its declared identity')
        reverse=text
        for patch in reversed(item['patches']):
            if reverse.count(patch['new'])!=patch['count']:
                raise ValueError('The full inverse source delta is not unique')
            reverse=reverse.replace(patch['new'],patch['old'])
        if reverse!=before:
            raise ValueError('The exact full parent body was not recovered')
        if item['role']=='driver':
            marker='    def save_report('
            suffix=text[text.index(marker):].encode('utf-8')
            expected=PLAN['complete_unchanged_scientific_suffix']
            if (suffix!=before[before.index(marker):].encode('utf-8')
                    or len(suffix)!=expected['bytes'] or digest(suffix)!=expected['sha256']):
                raise ValueError('The complete scientific loop and report/checkpoint suffix changed')
        answers.append((item,output))
    return answers

def main():
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--repo',type=Path,required=True)
    parser.add_argument('--outdir',type=Path,required=True)
    parser.add_argument('--verify-existing',action='store_true')
    args=parser.parse_args()
    answers=reconstruct(args.repo)
    args.outdir.mkdir(parents=True,exist_ok=True)
    for item,raw in answers:
        destination=args.outdir/item['output_basename']
        if args.verify_existing:
            if destination.read_bytes()!=raw:
                raise ValueError('Existing complete source differs: '+str(destination))
        else:
            if destination.exists():raise FileExistsError(destination)
            destination.write_bytes(raw)
    print(json.dumps(dict(schema=PLAN['schema'],complete_whole_source_bodies=len(answers),
        actual_entire_bodies_match=True,complete_inverse_parent_bytes_match=True,
        current_complete_source_roles=PLAN['current_complete_source_roles'],
        original_scientific_suffix_unchanged=True,
        numerical_execution=False,AST_or_compile_execution=False),sort_keys=True))

if __name__=='__main__':
    main()
